pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 collectAmt) public {
        // Restrict amounts to avoid overflow and ensure collect is possible
        vm.assume(deposit1 > 0 && deposit1 < type(uint256).max / 2);
        vm.assume(deposit2 > 0 && deposit2 < type(uint256).max / 2);
        vm.assume(deposit1 + deposit2 > collectAmt);
        vm.assume(collectAmt > 0);

        address depositor = makeAddr("depositor");

        // Initialize the contract
        vm.prank(address(this));
        c.SetMinSum(1);
        vm.prank(address(this));
        c.Initialized();

        // Perform two deposits
        vm.deal(depositor, deposit1 + deposit2 + 1 ether);
        vm.startPrank(depositor);
        c.Deposit{value: deposit1}();
        c.Deposit{value: deposit2}();
        vm.stopPrank();

        // Perform a collect
        vm.prank(depositor);
        c.Collect(collectAmt);

        // Compute expected balance = total deposits - collected amount
        uint256 expectedBalance = deposit1 + deposit2 - collectAmt;
        uint256 actualBalance = c.balances(depositor);

        // The invariant: after any successful collect, the balance equals total deposits minus collected amount
        assertTrue(actualBalance == expectedBalance);
    }
}

