pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 collectAmt) public {
        // Restrict amounts to prevent overflow; keep domain wide.
        vm.assume(deposit1 <= type(uint256).max / 2 && deposit2 <= type(uint256).max / 2);
        vm.assume(collectAmt <= deposit1);
        address depositor = address(0x1);
        address collector = address(0x2);
        vm.deal(depositor, deposit1 + deposit2);
        vm.deal(collector, 0);

        // Initialize
        c.Initialized();
        c.SetMinSum(0);

        // First deposit
        vm.prank(depositor);
        c.Deposit{value: deposit1}();

        // Collect part of first deposit
        vm.prank(depositor);
        c.Collect(collectAmt);

        // Second deposit
        vm.prank(depositor);
        c.Deposit{value: deposit2}();

        // Expected balance: deposit1 - collectAmt + deposit2
        uint256 expected = deposit1 - collectAmt + deposit2;
        uint256 actual = c.balances(depositor);
        assertTrue(actual == expected);
    }
}

