        vm.assume(deposit1 >= collectAmount && deposit2 >= collectAmount);
        vm.assume(deposit1 + deposit2 >= deposit1);

        vm.deal(sender, deposit1 + deposit2);
        vm.startPrank(sender);
        c.Deposit{value: deposit1}();
        c.Deposit{value: deposit2}();
        bool ok;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }
        vm.stopPrank();

        assertTrue(ok == false);
    }
}

